<script setup lang="ts">
import { computed, onMounted } from 'vue'; import { RouterLink } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { useDashboardStore } from '../stores/dashboard';
const auth = useAuthStore(); const store = useDashboardStore(); onMounted(() => { void store.fetch(); });
const stats = computed(() => [{ label: '分类', value: store.categories.data.length, path: '/categories' }, { label: '题目', value: store.problems.data.pagination.total, path: '/categories' }, { label: '错题', value: store.wrongs.data.pagination.total, path: '/wrongs' }, { label: '笔记', value: store.notes.data.pagination.total, path: '/notes' }, { label: '待办', value: store.todos.data.pagination.total, path: '/todos' }]);
const allEmpty = computed(() => !store.loading && stats.value.every((item) => item.value === 0) && !store.latestProgress);
</script>
<template><section class="mx-auto max-w-6xl p-5 md:p-10"><header class="border-b border-[var(--color-border)] pb-6"><p class="text-xs uppercase tracking-[0.18em] text-[var(--color-accent)]">Your learning desk</p><h2 class="mt-2 text-3xl font-semibold">你好，{{ auth.user?.displayName || '学习者' }}</h2><p class="mt-2 opacity-70">从今天的一个小进步开始，持续把算法能力练成肌肉记忆。</p></header><p v-if="store.loading" role="status" class="py-12 text-center">正在加载数据概览…</p><template v-else><p v-if="store.hasErrors" role="alert" class="mt-5 border border-amber-300 bg-amber-50 p-4 text-amber-800">部分数据加载失败，已展示其余可用内容。</p><div v-if="allEmpty" class="mt-6 border border-dashed p-10 text-center"><h3 class="font-semibold">还没有学习数据</h3><p class="mt-2 opacity-70">先去刷一道题，开启你的学习记录。</p><RouterLink class="mt-4 inline-block underline" to="/categories">开始刷题</RouterLink></div><template v-else><div class="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><RouterLink v-for="item in stats" :key="item.label" :to="item.path" class="border border-[var(--color-border)] p-4 hover:border-[var(--color-accent)]"><p class="text-sm opacity-70">{{ item.label }}</p><p class="mt-2 text-3xl font-semibold">{{ item.value }}</p></RouterLink></div><section class="mt-6 grid gap-6 lg:grid-cols-2"><article class="border p-5"><h3 class="font-semibold">总体学习进度</h3><p class="mt-4 text-4xl font-semibold">{{ store.averageProgress }}%</p><div class="mt-3 h-3 bg-black/10"><div class="h-3 bg-[var(--color-accent)]" :style="{ width: `${store.averageProgress}%` }" role="progressbar" :aria-valuenow="store.averageProgress" aria-valuemin="0" aria-valuemax="100" /></div><p class="mt-3 text-sm opacity-70">{{ store.latestProgress ? `最近记录：${store.latestProgress.title} · ${store.latestProgress.progress}%` : '还没有进度记录' }}</p></article><article class="border p-5"><h3 class="font-semibold">待办摘要</h3><div class="mt-4 grid grid-cols-3 gap-2 text-center"><div><p class="text-2xl font-semibold">{{ store.todos.data.pagination.total }}</p><p class="text-xs opacity-70">总数</p></div><div><p class="text-2xl font-semibold">{{ store.incompleteTodos.data.pagination.total }}</p><p class="text-xs opacity-70">未完成</p></div><div><p class="text-2xl font-semibold text-red-700">{{ store.overdueTodos.data.pagination.total }}</p><p class="text-xs opacity-70">逾期</p></div></div><RouterLink class="mt-5 inline-block text-sm underline" to="/todos">管理待办 →</RouterLink></article></section><section class="mt-6 border p-5"><div class="flex items-center justify-between"><h3 class="font-semibold">最近学习进度</h3><RouterLink class="text-sm underline" to="/progress">查看全部</RouterLink></div><ul v-if="store.progress.data.data.length" class="mt-4 grid gap-3 md:grid-cols-3"><li v-for="item in store.progress.data.data" :key="item.id" class="border p-3"><p class="font-semibold">{{ item.title }}</p><p class="mt-1 text-sm opacity-70">{{ item.progressDate }} · {{ item.progress }}%</p></li></ul><p v-else class="mt-4 text-sm opacity-70">暂无学习进度记录。</p></section><nav class="mt-6 flex flex-wrap gap-3" aria-label="快捷入口"><RouterLink v-for="item in [{ label: '刷题', path: '/categories' }, { label: '错题本', path: '/wrongs' }, { label: '笔记', path: '/notes' }, { label: '待办', path: '/todos' }, { label: '学习进度', path: '/progress' }]" :key="item.path" class="border px-4 py-2 text-sm hover:border-[var(--color-accent)]" :to="item.path">{{ item.label }} →</RouterLink></nav></template></template></section></template>
